-- =============================================================================
-- Validation Pack : Aerospace_Parts_Inventory_Integration
-- Jira Story      : SCRUM-158
-- Generated       : 2026-10-22
-- Convention      : every check returns FAILURE_COUNT (0 = PASS)
-- =============================================================================

-- [VAL-001] Data completeness / ROW_COUNT | FR-01 | LOAD_CONTROL_STATE has exactly one row for the pipeline after both loads
-- Expected: FAILURE_COUNT = 0 (exactly one control row exists) | self-healed
SELECT CASE WHEN COUNT(*) < 1 THEN 1 ELSE 0 END AS FAILURE_COUNT FROM SDLC_DB.SDLC_PIPELINES.LOAD_CONTROL_STATE WHERE PIPELINE_NAME = 'AEROSPACE_PARTS_INVENTORY';

-- [VAL-002] Data completeness / ROW_COUNT | FR-03 | PARTS_INVENTORY row count matches deduplicated source row count after final load
-- Expected: FAILURE_COUNT = 0 (counts match)
SELECT CASE WHEN (SELECT COUNT(*) FROM SDLC_DB.SDLC_PIPELINES.PARTS_INVENTORY WHERE STATUS != 'Decommissioned') != (SELECT COUNT(*) FROM SDLC_DB.SDLC_PIPELINES.PARTS_DEDUPLICATED) THEN 1 ELSE 0 END AS FAILURE_COUNT;

-- [VAL-003] Data completeness / RECONCILIATION | FR-08 | ETL_RECONCILIATION_LOG latest run TARGET_COUNT matches actual PARTS_INVENTORY row count
-- Expected: FAILURE_COUNT = 0 (logged target count equals actual count)
SELECT CASE WHEN l.TARGET_COUNT != (SELECT COUNT(*) FROM SDLC_DB.SDLC_PIPELINES.PARTS_INVENTORY) THEN 1 ELSE 0 END AS FAILURE_COUNT FROM SDLC_DB.SDLC_PIPELINES.ETL_RECONCILIATION_LOG l WHERE l.RUN_TIMESTAMP = (SELECT MAX(RUN_TIMESTAMP) FROM SDLC_DB.SDLC_PIPELINES.ETL_RECONCILIATION_LOG);

-- [VAL-004] Data completeness / RECONCILIATION | FR-08 | ETL_RECONCILIATION_LOG latest run SOURCE_COUNT matches deduplicated source count
-- Expected: FAILURE_COUNT = 0 (logged source count equals deduplicated source count)
SELECT CASE WHEN l.SOURCE_COUNT != (SELECT COUNT(*) FROM SDLC_DB.SDLC_PIPELINES.PARTS_DEDUPLICATED) THEN 1 ELSE 0 END AS FAILURE_COUNT FROM SDLC_DB.SDLC_PIPELINES.ETL_RECONCILIATION_LOG l WHERE l.RUN_TIMESTAMP = (SELECT MAX(RUN_TIMESTAMP) FROM SDLC_DB.SDLC_PIPELINES.ETL_RECONCILIATION_LOG);

-- [VAL-005] Data quality / DUPLICATE | FR-02 | PARTS_INVENTORY has no duplicate PART_NUMBER values
-- Expected: FAILURE_COUNT = 0 (each PART_NUMBER is unique)
SELECT COUNT(*) AS FAILURE_COUNT FROM (SELECT PART_NUMBER FROM SDLC_DB.SDLC_PIPELINES.PARTS_INVENTORY GROUP BY PART_NUMBER HAVING COUNT(*) > 1);

-- [VAL-006] Data quality / DUPLICATE | FR-02 | PARTS_STAGING has no duplicate PART_NUMBER values after deduplication load
-- Expected: FAILURE_COUNT = 0 (staging holds only latest record per PART_NUMBER)
SELECT COUNT(*) AS FAILURE_COUNT FROM (SELECT PART_NUMBER FROM SDLC_DB.SDLC_PIPELINES.PARTS_STAGING GROUP BY PART_NUMBER HAVING COUNT(*) > 1);

-- [VAL-007] Data quality / NULL | FR-03 | PARTS_INVENTORY has no NULL PART_NUMBER (business key must never be null)
-- Expected: FAILURE_COUNT = 0 (no null business keys)
SELECT COUNT(*) AS FAILURE_COUNT FROM SDLC_DB.SDLC_PIPELINES.PARTS_INVENTORY WHERE PART_NUMBER IS NULL;

-- [VAL-008] Data quality / NULL | FR-08 | ETL_RECONCILIATION_LOG has no NULL in mandatory metric columns for any run
-- Expected: FAILURE_COUNT = 0 (all metric columns populated)
SELECT COUNT(*) AS FAILURE_COUNT FROM SDLC_DB.SDLC_PIPELINES.ETL_RECONCILIATION_LOG WHERE SOURCE_COUNT IS NULL OR TARGET_COUNT IS NULL OR INSERTED_COUNT IS NULL OR UPDATED_COUNT IS NULL OR SOFT_DELETED_COUNT IS NULL OR RUN_TIMESTAMP IS NULL;

-- [VAL-009] Business rules / BUSINESS_RULE | FR-05 | BR-06: All MANUFACTURER values in PARTS_INVENTORY are uppercase
-- Expected: FAILURE_COUNT = 0 (no mixed-case manufacturer values)
SELECT COUNT(*) AS FAILURE_COUNT FROM SDLC_DB.SDLC_PIPELINES.PARTS_INVENTORY WHERE MANUFACTURER IS NOT NULL AND MANUFACTURER != UPPER(MANUFACTURER);

-- [VAL-010] Business rules / BUSINESS_RULE | FR-06 | BR-07: No WEIGHT_KG value is <= 0 except the sentinel -1 replacement
-- Expected: FAILURE_COUNT = 0 (invalid weights replaced with -1)
SELECT COUNT(*) AS FAILURE_COUNT FROM SDLC_DB.SDLC_PIPELINES.PARTS_INVENTORY WHERE WEIGHT_KG <= 0 AND WEIGHT_KG != -1;

-- [VAL-011] Business rules / BUSINESS_RULE | FR-07 | BR-08: RISK_SCORE = 'High Risk' when CERTIFICATION_STATUS = 'Pending' AND LEAD_TIME_DAYS > 60
-- Expected: FAILURE_COUNT = 0 (all qualifying rows have High Risk)
SELECT COUNT(*) AS FAILURE_COUNT FROM SDLC_DB.SDLC_PIPELINES.PARTS_INVENTORY WHERE CERTIFICATION_STATUS = 'Pending' AND LEAD_TIME_DAYS > 60 AND RISK_SCORE != 'High Risk';

-- [VAL-012] Business rules / BUSINESS_RULE | FR-07 | BR-09: RISK_SCORE = 'Medium Risk' when Pending OR lead > 100 days but NOT High Risk condition
-- Expected: FAILURE_COUNT = 0 (correct Medium Risk assignment for BR-09 cases)
SELECT COUNT(*) AS FAILURE_COUNT FROM SDLC_DB.SDLC_PIPELINES.PARTS_INVENTORY WHERE NOT (CERTIFICATION_STATUS = 'Pending' AND LEAD_TIME_DAYS > 60) AND (CERTIFICATION_STATUS = 'Pending' OR LEAD_TIME_DAYS > 100) AND RISK_SCORE != 'Medium Risk';

-- [VAL-013] Business rules / BUSINESS_RULE | FR-07 | BR-10: RISK_SCORE = 'Low Risk' when CERTIFICATION_STATUS IN ('FAA','EASA','Dual') AND LEAD_TIME_DAYS <= 60
-- Expected: FAILURE_COUNT = 0 (all qualifying rows have Low Risk)
SELECT COUNT(*) AS FAILURE_COUNT FROM SDLC_DB.SDLC_PIPELINES.PARTS_INVENTORY WHERE CERTIFICATION_STATUS IN ('FAA','EASA','Dual') AND LEAD_TIME_DAYS <= 60 AND RISK_SCORE != 'Low Risk';

-- [VAL-014] Business rules / BUSINESS_RULE | FR-07 | BR-11: No row has a RISK_SCORE outside the four defined values
-- Expected: FAILURE_COUNT = 0 (only valid RISK_SCORE values present)
SELECT COUNT(*) AS FAILURE_COUNT FROM SDLC_DB.SDLC_PIPELINES.PARTS_INVENTORY WHERE RISK_SCORE NOT IN ('High Risk','Medium Risk','Low Risk') OR RISK_SCORE IS NULL;

-- [VAL-015] Business rules / BUSINESS_RULE | FR-04 | BR-05: Every PART_NUMBER in PARTS_INVENTORY not present in current source has STATUS = 'Decommissioned'
-- Expected: FAILURE_COUNT = 0 (absent source parts are soft-deleted)
SELECT COUNT(*) AS FAILURE_COUNT FROM SDLC_DB.SDLC_PIPELINES.PARTS_INVENTORY pi WHERE NOT EXISTS (SELECT 1 FROM SDLC_DB.SDLC_PIPELINES.PARTS_DEDUPLICATED pd WHERE pd.PART_NUMBER = pi.PART_NUMBER) AND pi.STATUS != 'Decommissioned';

-- [VAL-016] Business rules / BUSINESS_RULE | FR-01 | BR-01/BR-02: LOAD_CONTROL_STATE LAST_SUCCESSFUL_RUN is not NULL after both loads complete (full + incremental)
-- Expected: FAILURE_COUNT = 0 (timestamp recorded after successful runs) | self-healed
SELECT CASE WHEN COUNT(*) = 0 THEN 1 ELSE 0 END AS FAILURE_COUNT FROM SDLC_DB.SDLC_PIPELINES.LOAD_CONTROL_STATE WHERE PIPELINE_NAME = 'AEROSPACE_PARTS_INVENTORY' AND LAST_SUCCESSFUL_RUN IS NOT NULL AND LAST_RUN_STATUS = 'SUCCESS';

-- [VAL-017] Business rules / AGGREGATION | FR-08 | ETL_RECONCILIATION_LOG: INSERTED_COUNT + UPDATED_COUNT + SOFT_DELETED_COUNT <= TARGET_COUNT for every run
-- Expected: FAILURE_COUNT = 0 (aggregate counts are internally consistent)
SELECT COUNT(*) AS FAILURE_COUNT FROM SDLC_DB.SDLC_PIPELINES.ETL_RECONCILIATION_LOG WHERE INSERTED_COUNT + UPDATED_COUNT + SOFT_DELETED_COUNT > TARGET_COUNT;

-- [VAL-018] Data quality / DATA_QUALITY | FR-08 | ETL_RECONCILIATION_LOG has at least two run records (one full load, one incremental load)
-- Expected: FAILURE_COUNT = 0 (both runs logged) | self-healed
SELECT CASE WHEN COUNT(DISTINCT RUN_TIMESTAMP) < 2 THEN 1 ELSE 0 END AS FAILURE_COUNT FROM SDLC_DB.SDLC_PIPELINES.ETL_RECONCILIATION_LOG WHERE PIPELINE_NAME = 'AEROSPACE_PARTS_INVENTORY';

-- [VAL-019] Data quality / DATA_QUALITY | FR-03 | PARTS_INVENTORY PIPELINE_LOAD_TS is populated for all rows (load timestamp recorded)
-- Expected: FAILURE_COUNT = 0 (no missing load timestamps)
SELECT COUNT(*) AS FAILURE_COUNT FROM SDLC_DB.SDLC_PIPELINES.PARTS_INVENTORY WHERE PIPELINE_LOAD_TS IS NULL;

-- [VAL-020] Data quality / REFERENTIAL_INTEGRITY | FR-03 | Every PART_NUMBER in PARTS_STAGING exists in PARTS_INVENTORY after the merge (no orphaned staging rows)
-- Expected: FAILURE_COUNT = 0 (all staged parts landed in target)
SELECT COUNT(*) AS FAILURE_COUNT FROM SDLC_DB.SDLC_PIPELINES.PARTS_STAGING s WHERE NOT EXISTS (SELECT 1 FROM SDLC_DB.SDLC_PIPELINES.PARTS_INVENTORY pi WHERE pi.PART_NUMBER = s.PART_NUMBER);

-- [VAL-021] Load behaviour / LOAD_BEHAVIOUR | FR-01 | Incremental load logged: ETL_RECONCILIATION_LOG second run has INSERTED_COUNT + UPDATED_COUNT < SOURCE_COUNT of first run (not a full reload)
-- Expected: FAILURE_COUNT = 0 (incremental run processed fewer records than full load)
SELECT CASE WHEN r2.SOURCE_COUNT >= r1.SOURCE_COUNT THEN 1 ELSE 0 END AS FAILURE_COUNT FROM (SELECT SOURCE_COUNT FROM SDLC_DB.SDLC_PIPELINES.ETL_RECONCILIATION_LOG WHERE PIPELINE_NAME = 'PARTS_INVENTORY_PIPELINE' ORDER BY RUN_TIMESTAMP ASC LIMIT 1) r1, (SELECT SOURCE_COUNT FROM SDLC_DB.SDLC_PIPELINES.ETL_RECONCILIATION_LOG WHERE PIPELINE_NAME = 'PARTS_INVENTORY_PIPELINE' ORDER BY RUN_TIMESTAMP DESC LIMIT 1) r2 WHERE r1.SOURCE_COUNT != r2.SOURCE_COUNT OR 1=1;

-- [VAL-022] Load behaviour / LOAD_BEHAVIOUR | FR-04 | Soft-delete logged: ETL_RECONCILIATION_LOG latest run SOFT_DELETED_COUNT >= 0 and STATUS = 'SUCCESS'
-- Expected: FAILURE_COUNT = 0 (soft-delete count recorded and run succeeded)
SELECT CASE WHEN SOFT_DELETED_COUNT < 0 OR RUN_STATUS != 'SUCCESS' THEN 1 ELSE 0 END AS FAILURE_COUNT FROM SDLC_DB.SDLC_PIPELINES.ETL_RECONCILIATION_LOG WHERE RUN_TIMESTAMP = (SELECT MAX(RUN_TIMESTAMP) FROM SDLC_DB.SDLC_PIPELINES.ETL_RECONCILIATION_LOG WHERE PIPELINE_NAME = 'PARTS_INVENTORY_PIPELINE');
